def evaluate(tree: Tree) -> int:
    if tree.left is None or tree.right is None:
        return tree.value
    if tree.value == "+":
        return evaluate(tree.left) + evaluate(tree.right)
    return evaluate(tree.left) * evaluate(tree.right)

